sp_LancarCaixa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_LancarCaixa`(\n\n    IN p_idCaixa              INT,\n\n    IN p_idEmpresa            INT,\n\n    IN p_idUsuario            INT,\n\n    IN p_idFormaPagamento     INT,\n\n    IN p_idCategoriaFinanceira INT,\n\n    IN p_valor                DECIMAL(10,2),\n\n    IN p_descricao            VARCHAR(300),\n\n    IN p_referencia           VARCHAR(100),\n\n    IN p_tipoLancamento       VARCHAR(20),\n\n    IN p_pedido_id            INT,\n\n    IN p_cliente_id           INT,\n\n    IN p_contaReceber_id      INT\n\n)\nBEGIN\n\n    DECLARE v_nomeFP VARCHAR(80);\n\n\n\n    SELECT nome INTO v_nomeFP\n\n    FROM FormaPagamento\n\n    WHERE idFormaPagamento = p_idFormaPagamento LIMIT 1;\n\n\n\n    \n\n    IF UPPER(v_nomeFP) LIKE '%DINHEIRO%' OR UPPER(v_nomeFP) LIKE '%ESPECIE%' THEN\n\n        IF p_tipoLancamento IN ('VENDA', 'SUPRIMENTO', 'RECEBIMENTO', 'MANUAL') THEN\n\n            UPDATE Caixa SET saldoDinheiro = saldoDinheiro + p_valor WHERE idCaixa = p_idCaixa;\n\n        ELSEIF p_tipoLancamento IN ('DESPESA', 'SANGRIA') THEN\n\n            UPDATE Caixa SET saldoDinheiro = GREATEST(saldoDinheiro - p_valor, 0) WHERE idCaixa = p_idCaixa;\n\n        END IF;\n\n    END IF;\n\n\n\n    INSERT INTO LancamentoCaixa (\n\n        idCaixa, idEmpresa, idUsuario,\n\n        idFormaPagamento, idCategoriaFinanceira,\n\n        valor, dthLancamento,\n\n        descricao, referencia,\n\n        tipoLancamento, pedido_id, cliente_id, contaReceber_id\n\n    ) VALUES (\n\n        p_idCaixa, p_idEmpresa, p_idUsuario,\n\n        p_idFormaPagamento, p_idCategoriaFinanceira,\n\n        p_valor, CONVERT_TZ(NOW(), '+00:00', '-03:00'),\n\n        p_descricao, p_referencia,\n\n        p_tipoLancamento, p_pedido_id, p_cliente_id, p_contaReceber_id\n\n    );\n\n\n\n    SELECT LAST_INSERT_ID() AS idLancamento;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
